--- a/src/main/java/clinic/billing/PaymentMatcher.java
+++ b/src/main/java/clinic/billing/PaymentMatcher.java
@@ -12,15 +12,30 @@ public class PaymentMatcher {

     private final ReceiptRepository receipts;

-    public boolean match(Payment payment) {
-        return false;
+    public boolean match(Payment payment) {
+        Receipt receipt = receipts.byId(payment.receiptId());
+
+        if (receipt == null || receipt.isPaid()) {
+            return false;
+        }
+
+        BigDecimal expected = receipt.total();
+        BigDecimal actual = payment.amount();
+
+        if (!expected.equals(actual)) {
+            return false;
+        }
+
+        receipts.markPaid(receipt.id(), payment.id());
+
+        return true;
     }

     public List<Receipt> unpaid() {
         return receipts.unpaid();
     }
 }
